    },
    {
      "name": "Pricing Predictability",
      "description": "Clarity of pricing model, presence of tiered or usage‑based rates, discounts for committed spend, and historical variance between quoted and billed amounts."
    },
    {
      "name": "Advertised vs. Actual SLA",
      "description": "Comparison of vendor‑published service‑level agreements (uptime, latency, response time) against third‑party monitoring data and customer‑reported breach incidents."
    },
    {
      "name": "On‑Prem / Hybrid Readiness",
      "description": "Availability of edge, private‑cloud, or on‑prem deployments; compatibility with existing data‑center hardware; licensing model for non‑public cloud usage."
    },
    {
      "name": "Customer Sentiment & Trust",
      "description": "Qualitative and quantitative signals from reviews, analyst reports, case studies, and social media regarding reliability, support quality, and overall satisfaction."
    }
  ],
  "evidence_gathering_plan": {
    "sources": [
      {
        "type": "Vendor Documentation",
        "items": [
          "Product datasheets",
          "Technical whitepapers",
          "Pricing calculators",
          "SLA contracts"
        ],
        "purpose": "Capture advertised architecture, pricing structures, SLA terms, and on‑prem offerings."
      },
      {
        "type": "Third‑Party Benchmarks",
        "items": [
          "Cloud Spectator",
          "SPEC Cloud",
          "MLPerf",
          "Gartner Peer Insights performance tables"
        ],
        "purpose": "Obtain independent latency and throughput measurements for comparable workloads."
      },
      {
        "type": "Financial & Billing Audits",
        "items": [
          "Customer invoice samples (where available)",
          "Public cost‑analysis blogs",
          "Marketplace pricing history"
        ],
        "purpose": "Assess pricing predictability and variance between quoted vs. actual spend."
      },
      {
        "type": "Monitoring & Incident Data",
        "items": [
          "UptimeRobot / Statuspage archives",
          "Downtime.com incident reports",
          "Open‑source outage aggregators"
        ],
        "purpose": "Validate actual SLA performance against vendor claims."
      },
      {
        "type": "Customer Voice",
        "items": [
          "Gartner Peer Insights, G2, TrustRadius reviews",
          "LinkedIn & Reddit discussion threads",
          "Direct interview transcripts (5‑10 enterprise customers per vendor)",
          "Analyst briefings (Forrester, IDC)"
        ],
        "purpose": "Gauge sentiment, perceived reliability, and support experience."
      },
      {
        "type": "Technical Community & Open‑Source",
        "items": [
          "GitHub issues / pull requests for SDKs & connectors",
          "Stack Overflow tags",
          "Community forums"
        ],
        "purpose": "Identify real‑world integration challenges and on‑prem deployment feedback."
      }
    ],
    "methodology": [
      {
        "step": "Document Extraction",
        "actions": [
          "Scrape vendor sites for architecture diagrams, component lists, and on‑prem product pages.",
          "Parse pricing tables into a normalized spreadsheet (USD per hour, per GB, per request)."
        ]
      },
      {
        "step": "Benchmark Mapping",
        "actions": [
          "Select three representative enterprise workloads (e.g., batch inference, streaming analytics, security scanning).",
          "Map each benchmark’s reported latency/throughput to the vendor’s claimed specifications."
        ]
      },
      {
        "step": "SLA Gap Analysis",
        "actions": [
          "Create a time‑series of reported uptime from status pages.",
          "Calculate actual availability % over the last 12 months and compare to advertised SLA."
        ]
      },
      {
        "step": "Pricing Variance Calculation",
        "actions": [
          "For each vendor, compute the coefficient of variation (CV) between quoted price (calculator) and real‑world invoice data.",
          "Flag any >10% CV as low predictability."
        ]
      },
      {
        "step": "Sentiment Scoring",
        "actions": [
          "Run NLP sentiment analysis on review corpora (scale -1 to +1).",
          "Weight sentiment by reviewer credibility (e.g., verified enterprise vs. individual)."
        ]
      },
      {
        "step": "On‑Prem Feasibility Review",
        "actions": [
          "Cross‑check hardware compatibility matrices with top 5 enterprise data‑center vendors.",
          "Document licensing constraints (per‑core, per‑node, subscription)."
        ]
      }
    ],
    "timeline": {
      "Week 1": "Kick‑off, define workload benchmarks, collect vendor docs.",
      "Week 2": "Extract pricing & SLA data, begin third‑party benchmark retrieval.",
      "Week 3": "Gather customer review datasets, initiate sentiment analysis.",
      "Week 4": "Perform SLA gap analysis, compute pricing variance, draft architecture comparison matrix.",
      "Week 5": "Conduct direct customer interviews, validate on‑prem readiness.",
      "Week 6": "Synthesize findings, apply weighting (Latency 30%, Pricing 20%, SLA 20%, Architecture 15%, Sentiment 10%, On‑Prem 5%), produce final comparative report."
    },
    "deliverables": [
      "Evidence Matrix (source → dimension → confidence score)",
      "Normalized scoring table per competitor",
      "Executive summary with recommendation matrix",
      "Appendix of raw data extracts and interview transcripts"
    ]
  }
}
